import os
import resource
from ..core.dataset.dataset import Dataset, TimeSeriesDataset
from typing import Callable, List, Optional
import torch
from torchvision.datasets.utils import download_and_extract_archive, check_integrity
import pandas as pd
import numpy as np

class Traffic(TimeSeriesDataset):
    """Traffic dataset for road occupancy rates in the San Francisco Bay area.

    The raw data is sourced from the California Department of Transportation
    and is available at http://pems.dot.ca.gov. This dataset contains 48 months
    (2015-2016) of hourly road occupancy rates (between 0 and 1) measured by
    different sensors on freeways in the San Francisco Bay area.

    Attributes:
        name (str): Name of the dataset.
        num_features (int): Number of features in the dataset.
        length (int): Length of the dataset.
        freq (str): Frequency of the data points.

    Methods:
        download(): Downloads and extracts the dataset.
        _load(): Loads the dataset into a NumPy array.
    """

    name:str= 'traffic'
    num_features: int = 862
    length : int = 17544
    freq:str = 'h'
    
    def download(self) -> None:
        # local-data skip for Traffic
        candidates = [
            os.path.join(self.dir, 'traffic.txt'),
            os.path.join(self.dir, 'traffic.csv'),
            os.path.join(self.root, 'traffic', 'traffic.txt'),
            os.path.join(self.root, 'traffic', 'traffic.csv'),
            os.path.join(self.root, 'Traffic', 'traffic.txt'),
            os.path.join(self.root, 'Traffic', 'traffic.csv'),
        ]
        if any(os.path.exists(x) for x in candidates):
            return
        download_and_extract_archive(
            "https://raw.githubusercontent.com/laiguokun/multivariate-time-series-data/master/traffic/traffic.txt.gz",
            self.dir,
            filename="traffic.txt.gz",
            md5="db745d0c9f074159581a076cbb3f23d6",
        )


    def _load(self) -> np.ndarray:
        candidates = [
            os.path.join(self.dir, 'traffic.txt'),
            os.path.join(self.dir, 'traffic.csv'),
            os.path.join(self.root, 'traffic', 'traffic.txt'),
            os.path.join(self.root, 'traffic', 'traffic.csv'),
            os.path.join(self.root, 'Traffic', 'traffic.txt'),
            os.path.join(self.root, 'Traffic', 'traffic.csv'),
        ]

        self.file_name = None
        for candidate in candidates:
            if os.path.exists(candidate):
                self.file_name = candidate
                break

        if self.file_name is None:
            self.file_name = os.path.join(self.dir, 'traffic.txt')

        if self.file_name.endswith('.csv'):
            df = pd.read_csv(self.file_name)
            # Common traffic.csv format: first column is date/time, remaining 862 columns are sensors.
            if df.shape[1] == self.num_features + 1:
                df = df.iloc[:, 1:]
            elif df.shape[1] != self.num_features:
                # Fallback for no-header csv/txt-like files.
                df = pd.read_csv(self.file_name, header=None)
                if df.shape[1] == self.num_features + 1:
                    df = df.iloc[:, 1:]
                elif df.shape[1] != self.num_features:
                    raise ValueError(f"Unexpected Traffic data shape from {self.file_name}: {df.shape}")
        else:
            df = pd.read_csv(self.file_name, header=None)
            if df.shape[1] == self.num_features + 1:
                df = df.iloc[:, 1:]
            elif df.shape[1] != self.num_features:
                raise ValueError(f"Unexpected Traffic data shape from {self.file_name}: {df.shape}")

        df = df.apply(pd.to_numeric, errors='coerce')
        df = df.dropna(axis=0, how='any')

        self.df = df.copy()
        self.df['date'] = pd.date_range(start='01/01/2015 00:00', periods=len(self.df), freq='1H')
        self.dates = pd.DataFrame({'date': self.df['date']})
        self.data = df.to_numpy()
        return self.data
